def parse_metrics_jsonl(logdir_name):
    """Parse metrics.jsonl and extract checkpoint-level data."""
    path = os.path.join(LOGDIR, logdir_name, "metrics.jsonl")
    if not os.path.exists(path):
        return None

    checkpoints = {}
    with open(path) as f:
        for line in f:
            try:
                d = json.loads(line.strip())
            except:
                continue
            step = d.get("step", None)
            if step is None:
                continue
            if step not in checkpoints:
                checkpoints[step] = {}
            checkpoints[step].update(d)

    # Extract at key steps
    result = {}
    for step, data in sorted(checkpoints.items()):
        if "eval_return" in data or "value_mean" in data:
            entry = {"step": step}
            for k in ["eval_return", "value_mean", "ve_ratio", "actor_entropy",
                       "value_loss", "model_loss", "reward_loss",
                       "gate_dt_mean", "gate_dt_1_frac", "gate_dt_std",
                       "gate_empirical_entropy", "gate_entropy_ratio"]:
                if k in data:
                    entry[k] = data[k]
            # Compute ve_ratio if not present but value_mean and eval_return are
            if "ve_ratio" not in entry and "value_mean" in entry and "eval_return" in entry:
                if entry["eval_return"] > 0:
                    entry["ve_ratio"] = entry["value_mean"] / entry["eval_return"]
            result[step] = entry
    return result

# Also try to use pre-aggregated data
preag_exps = preag.get("experiments", {})

# Merge: prefer pre-aggregated, fallback to metrics.jsonl
all_data = {}
for exp_id, cfg in EXP_CONFIG.items():
    logdir_name = cfg["logdir"]

    # Check pre-aggregated
    preag_key = None
    for k in preag_exps:
        if preag_exps[k].get("logdir") == logdir_name:
            preag_key = k
            break

    if preag_key:
        cps = preag_exps[preag_key]["checkpoints"]
        checkpoints = {cp["step"]: cp for cp in cps}
    else:
        checkpoints = parse_metrics_jsonl(logdir_name)

    if checkpoints is None:
        checkpoints = {}

    all_data[exp_id] = {"config": cfg, "checkpoints": checkpoints}

# Get baseline v/e at key steps for normalization
baseline_ve = {}
bl = all_data.get("exp_001_baseline", {}).get("checkpoints", {})
for step in [35000, 45000, 65000, 105000]:
    if step in bl and "ve_ratio" in bl[step]:
        baseline_ve[step] = bl[step]["ve_ratio"]

# Also get baseline seed 2 v/e
baseline_s2_ve = {}
bl2 = all_data.get("exp_009a_baseline_s2", {}).get("checkpoints", {})
for step in [35000, 45000, 65000, 105000]:
    if step in bl2 and "ve_ratio" in bl2[step]:
        baseline_s2_ve[step] = bl2[step]["ve_ratio"]

# Summary for each experiment
summary = []
for exp_id, ed in all_data.items():
    cfg = ed["config"]
    cps = ed["checkpoints"]

    if not cps:
        summary.append({
            "exp_id": exp_id, "env": cfg["env"], "seed": cfg["seed"],
            "gate_enabled": cfg["gate_enabled"], "dt_embed_dim": cfg["dt_embed_dim"],
            "subsample": cfg["subsample"], "fixed_dt": cfg["fixed_dt"],
            "imag_horizon": cfg["imag_horizon"],
            "max_step": "N/A", "eval_final": "N/A", "eval_peak": "N/A",
            "ve_35k": "N/A", "ve_45k": "N/A", "ve_65k": "N/A", "ve_105k": "N/A",
            "nve_35k": "N/A", "nve_45k": "N/A", "nve_65k": "N/A", "nve_105k": "N/A",
            "gate_dt_mean_final": "N/A", "gate_dt_1_frac_final": "N/A",
            "claims": cfg["claims"]
        })
        continue

    sorted_steps = sorted(cps.keys())
    max_step = sorted_steps[-1]

    # eval_return: final and peak
    eval_returns = [(s, cps[s]["eval_return"]) for s in sorted_steps if "eval_return" in cps[s]]
    eval_final = eval_returns[-1][1] if eval_returns else None
    eval_peak = max(eval_returns, key=lambda x: x[1])[1] if eval_returns else None

    # v/e ratio at key steps
    def get_ve(step):
        if step in cps and "ve_ratio" in cps[step]:
            return cps[step]["ve_ratio"]
        # Try nearest step within 2500
        for s in sorted_steps:
            if abs(s - step) <= 2500 and "ve_ratio" in cps[s]:
                return cps[s]["ve_ratio"]
        return None

    ve_35k = get_ve(35000)
    ve_45k = get_ve(45000)
    ve_65k = get_ve(65000)
    ve_105k = get_ve(105000)

    # Normalized v/e (use seed-matched baseline)
    ref_ve = baseline_s2_ve if cfg["seed"] == 2 else baseline_ve

    def norm_ve(ve_val, step):
        if ve_val is None or step not in ref_ve or ref_ve[step] == 0:
            return None
        return ve_val / ref_ve[step]

    nve_35k = norm_ve(ve_35k, 35000)
    nve_45k = norm_ve(ve_45k, 45000)
    nve_65k = norm_ve(ve_65k, 65000)
    nve_105k = norm_ve(ve_105k, 105000)

    # Gate metrics (final checkpoint)
    gate_dt_mean = None
    gate_dt_1_frac = None
    for s in reversed(sorted_steps):
        if "gate_dt_mean" in cps[s]:
            gate_dt_mean = cps[s]["gate_dt_mean"]
            gate_dt_1_frac = cps[s].get("gate_dt_1_frac")
            break

    def fmt(v, dec=2):
        if v is None:
            return "N/A"
        return f"{v:.{dec}f}"

    summary.append({
        "exp_id": exp_id, "env": cfg["env"], "seed": cfg["seed"],
        "gate_enabled": cfg["gate_enabled"], "dt_embed_dim": cfg["dt_embed_dim"],
        "subsample": cfg["subsample"], "fixed_dt": cfg["fixed_dt"],
        "imag_horizon": cfg["imag_horizon"],
        "max_step": max_step,
        "eval_final": fmt(eval_final, 1),
        "eval_peak": fmt(eval_peak, 1),
        "ve_35k": fmt(ve_35k, 3),
        "ve_45k": fmt(ve_45k, 3),
        "ve_65k": fmt(ve_65k, 3),
        "ve_105k": fmt(ve_105k, 3),
        "nve_35k": fmt(nve_35k, 2),
        "nve_45k": fmt(nve_45k, 2),
        "nve_65k": fmt(nve_65k, 2),
        "nve_105k": fmt(nve_105k, 2),
        "gate_dt_mean_final": fmt(gate_dt_mean, 2) if gate_dt_mean else "N/A",
        "gate_dt_1_frac_final": fmt(gate_dt_1_frac, 2) if gate_dt_1_frac is not None else "N/A",
        "claims": cfg["claims"],
        # raw values for CSV
        "_eval_final": eval_final, "_eval_peak": eval_peak,
        "_ve_35k": ve_35k, "_ve_45k": ve_45k, "_ve_65k": ve_65k, "_ve_105k": ve_105k,
        "_nve_35k": nve_35k, "_nve_45k": nve_45k, "_nve_65k": nve_65k, "_nve_105k": nve_105k,
    })

# Print JSON summary
print(json.dumps(summary, indent=2))
